import XCTest

final class OpenDMTests: XCTestCase {
    func testOpenDM() {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        let bob = app.staticTexts.matching(NSPredicate(format: "label == %@", "Bob")).firstMatch
        XCTAssertTrue(bob.waitForExistence(timeout: 10), "Bob should appear in the chat list")
        bob.tap()
        sleep(3)
        XCTAssertTrue(app.staticTexts["Bob"].firstMatch.exists, "Bob's conversation should be open")
    }
}
EOF
xcodebuild test -quiet -project UIDriver.xcodeproj -scheme UIDriverTests -destination 'platform=iOS Simulator,id=0AE30C2A-80F9-4A7E-9A1A-DF76FA001495' -derivedDataPath DerivedData

